#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    cin >> s;

    int sum = 0;
    bool ok = true;

    while (ok) {
        ok = false;

        for (size_t i = 0; i + 1 < s.size(); ++i) {
            if (s[i] == 'V' && s[i + 1] == 'K') {
                ok = true;
                s.erase(i, 2);
                ++sum;
                break;
            }
        }
    }

    bool yes = false;
    for (size_t i = 1; i < s.size(); ++i) {
        if (s[i] == s[i - 1]) {
            yes = true;
            break;
        }
    }

    cout << sum + (yes ? 1 : 0);
    return 0;
}

